namespace Notifications;

/// <summary>Computes the backoff delay before the next delivery attempt.</summary>
public sealed class RetryPolicy
{
    public int NextDelay(int attempt, Channel channel, bool serverBusy)
    {
        if (attempt <= 0)
            return 0;
        if (attempt > 10)
            return 3600;

        int delay = GetBaseDelay(channel) * attempt;
        delay = ApplyServerBusyDelay(delay, serverBusy);
        return ApplyDelayLimits(delay, attempt);
    }

    private static int GetBaseDelay(Channel channel)
    {
        return channel switch
        {
            Channel.Email => 30,
            Channel.Sms => 10,
            Channel.Push => 5,
            _ => 15
        };
    }

    private static int ApplyServerBusyDelay(int delay, bool serverBusy)
    {
        return serverBusy && delay < 600 ? delay * 2 : delay;
    }

    private static int ApplyDelayLimits(int delay, int attempt)
    {
        if (delay > 3600)
            return 3600;
        if (delay < 1)
            return 1;
        if (attempt > 7)
            return delay + 100;

        return delay;
    }
}
